<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { Message } from '@arco-design/web-vue'
import PageHeader from '@/components/PageHeader.vue'
import { useSessionStore } from '@/stores/session'

interface Envelope<T> { data: T }
interface Organization { id: string; name: string }
interface Project { id: string; organizationId: string; name: string; code: string }
interface Context { organizations: Organization[]; projects: Record<string, Project[]> }
interface Profile { id: string; name: string; browser: 'chromium' | 'firefox' | 'webkit'; baseUrl: string; viewportWidth: number; viewportHeight: number; enabled: boolean; version: number; updatedAt: string }
interface PageObject { id: string; name: string; selectorValue: string; description: string; updatedAt: string }
type StepType = 'NAVIGATE' | 'FILL' | 'CLICK' | 'ASSERT_VISIBLE' | 'ASSERT_TEXT' | 'WAIT' | 'SCREENSHOT'
interface Step { id: string; type: StepType; name: string; selector?: string; pageObjectId?: string; value?: string; url?: string; expectedText?: string; timeoutMillis?: number }
interface Scenario { id: string; browserProfileId: string; name: string; description: string; failureStrategy: 'STOP' | 'CONTINUE'; variables: Record<string, string>; steps: Step[]; version: number; updatedAt: string }
interface FunctionalPlan { id: string; planCode: string; name: string; status: string; caseCount: number }
interface Schedule { id: string; scenarioId: string; functionalPlanId?: string; functionalPlanName?: string; name: string; cronExpression: string; timezone: string; timeoutSeconds: number; maxRetryAttempts: number; retryBackoffSeconds: number; enabled: boolean; lastExecutionId?: string; lastExecutionStatus?: string; lastTriggeredAt?: string }
interface Execution { id: string; taskId: string; scenarioId: string; scenarioName: string; scenarioVersion: number; browser: string; scheduleId?: string; functionalPlanId?: string; functionalPlanName?: string; retryOfExecutionId?: string; retryAttempt: number; status: string; statusCode?: string; statusMessage?: string; runnerId?: string; requestedAt: string; deadlineAt: string }
interface Runner { runnerId: string; runnerVersion: string; executionEnabled: boolean; trusted: boolean; trustStatus: string; maxConcurrentTasks: number; activeTaskCount: number; heartbeatAt: string }
interface Report { execution: Execution; summary: { totalSteps: number; passedSteps: number; failedSteps: number; totalDurationMillis: number }; steps: Array<{ id: string; stepSequence: number; stepName: string; stepType: StepType; outcome: string; durationMillis: number; errorMessage?: string; occurredAt: string }>; artifacts: Array<{ id: string; artifactType: string; originalName: string; sizeBytes: number; createdAt: string }> }

const session = useSessionStore(); const context = ref<Context | null>(null); const projectId = computed({ get: () => session.projectId, set: (value: string) => session.selectProject(value) }); const loading = ref(true); const profiles = ref<Profile[]>([]); const pageObjects = ref<PageObject[]>([]); const scenarios = ref<Scenario[]>([]); const functionalPlans = ref<FunctionalPlan[]>([]); const schedules = ref<Schedule[]>([]); const executions = ref<Execution[]>([]); const runners = ref<Runner[]>([]); const selectedScenarioId = ref(''); const saving = ref(false); const report = ref<Report | null>(null); const reportVisible = ref(false); const profileVisible = ref(false); const objectVisible = ref(false); const scenarioVisible = ref(false); const executeVisible = ref(false); const scheduleVisible = ref(false); const executionScenario = ref<Scenario | null>(null)
let timer: number | undefined
let assetsRequest = 0
let reportRequest = 0
const reportExecutionId = ref('')
const reportError = ref('')
const loadError = ref('')
const profileForm = reactive({ id: '', name: '', browser: 'chromium' as Profile['browser'], baseUrl: '', viewportWidth: 1440, viewportHeight: 900, enabled: true })
const objectForm = reactive({ id: '', name: '', selectorValue: '', description: '' })
const scenarioForm = reactive<{ id: string; name: string; description: string; browserProfileId: string; failureStrategy: 'STOP' | 'CONTINUE'; variablesText: string; steps: Step[] }>({ id: '', name: '', description: '', browserProfileId: '', failureStrategy: 'STOP', variablesText: '{}', steps: [] })
const executeForm = reactive({ timeoutSeconds: 300, functionalPlanId: '' })
const scheduleForm = reactive({ id: '', scenarioId: '', functionalPlanId: '', name: '', cronExpression: '0 0 9 ? * MON-FRI', timezone: 'Asia/Shanghai', timeoutSeconds: 300, maxRetryAttempts: 1, retryBackoffSeconds: 30, enabled: true })
const projects = computed(() => context.value?.organizations.flatMap((item) => context.value?.projects[item.id] ?? []) ?? [])
const selectedProject = computed(() => projects.value.find((item) => item.id === projectId.value))
const selectedScenario = computed(() => scenarios.value.find((item) => item.id === selectedScenarioId.value) ?? null)
const activeRunner = computed(() => runners.value.find((item) => item.trusted) ?? runners.value[0])
const executable = computed(() => runners.value.filter((item) => item.trusted && item.executionEnabled))
const firstFailedStep = computed(() => report.value?.steps.find((item) => item.outcome === 'FAILED') ?? null)
const visualArtifacts = computed(() => report.value?.artifacts.filter((item) => item.artifactType === 'SCREENSHOT' || item.artifactType === 'VIDEO') ?? [])
const statusText = (value: string) => ({ QUEUED: '排队中', ACCEPTED: '已接收', RUNNING: '运行中', CANCELLING: '取消中', SUCCEEDED: '成功', FAILED: '失败', REJECTED: '已拒绝', CANCELLED: '已取消', TIMED_OUT: '已超时' }[value] ?? value)
const statusColor = (value: string) => ({ QUEUED: 'arcoblue', ACCEPTED: 'cyan', RUNNING: 'orange', SUCCEEDED: 'green', FAILED: 'red', REJECTED: 'orange', CANCELLED: 'gray', TIMED_OUT: 'red' }[value] ?? 'gray')
const stepMeta: Record<StepType, string> = { NAVIGATE: '导航', FILL: '填写', CLICK: '点击', ASSERT_VISIBLE: '可见断言', ASSERT_TEXT: '文本断言', WAIT: '等待', SCREENSHOT: '截图' }
const date = (value?: string) => value ? new Intl.DateTimeFormat('zh-CN', { dateStyle: 'short', timeStyle: 'short' }).format(new Date(value)) : '—'
const size = (value: number) => value < 1024 ? `${value} B` : `${(value / 1024 / 1024).toFixed(1)} MB`
async function read<T>(url: string, init?: RequestInit): Promise<T> { const response = await fetch(url, { credentials: 'include', ...init }); const body = await response.json().catch(() => ({})) as Envelope<T> & { message?: string }; if (!response.ok) throw new Error(body.message ?? '请求失败，请稍后重试'); return body.data }
async function mutate<T>(url: string, method: 'POST' | 'PUT' | 'DELETE', body?: unknown): Promise<T> { const csrf = await read<{ token: string; headerName: string }>('/api/v1/auth/csrf'); return read<T>(url, { method, headers: { 'Content-Type': 'application/json', [csrf.headerName]: csrf.token }, body: body === undefined ? undefined : JSON.stringify(body) }) }
async function loadAssets() { if (!projectId.value) return; const request = ++assetsRequest; const project = projectId.value; const base = `/api/v1/projects/${project}/ui-automation`; const [profileData, objectData, scenarioData, executionData, runnerData, planData, scheduleData] = await Promise.all([read<Profile[]>(`${base}/browser-profiles`), read<PageObject[]>(`${base}/page-objects`), read<Scenario[]>(`${base}/scenarios`), read<Execution[]>(`${base}/executions`), read<Runner[]>(`${base}/runner-status`), read<FunctionalPlan[]>(`/api/v1/projects/${projectId.value}/functional/plans`), read<Schedule[]>(`${base}/schedules`)]); if (request !== assetsRequest || project !== projectId.value) return; loadError.value = ''; profiles.value = profileData; pageObjects.value = objectData; scenarios.value = scenarioData; executions.value = executionData; runners.value = runnerData; functionalPlans.value = planData; schedules.value = scheduleData; if (!scenarios.value.some((item) => item.id === selectedScenarioId.value)) selectedScenarioId.value = scenarios.value[0]?.id ?? '' }
async function load() { loading.value = true; try { context.value = await read<Context>('/api/v1/access/context'); projectId.value = session.resolveProjectId(projects.value); await loadAssets() } catch (error) { Message.error(error instanceof Error ? error.message : '加载 Web UI 自动化资源失败') } finally { loading.value = false } }
async function changeProject() { assetsRequest++; closeReport(); profileVisible.value = objectVisible.value = scenarioVisible.value = executeVisible.value = scheduleVisible.value = false; profiles.value = []; pageObjects.value = []; scenarios.value = []; functionalPlans.value = []; schedules.value = []; executions.value = []; runners.value = []; executionScenario.value = null; selectedScenarioId.value = ''; loadError.value = ''; try { await loadAssets() } catch (error) { Message.error(error instanceof Error ? error.message : '切换项目失败') } }
function resetProfile() { Object.assign(profileForm, { id: '', name: '', browser: 'chromium', baseUrl: '', viewportWidth: 1440, viewportHeight: 900, enabled: true }) }
function editProfile(item: Profile) { Object.assign(profileForm, item); profileVisible.value = true }
async function saveProfile() { saving.value = true; try { const payload = { ...profileForm }; const base = `/api/v1/projects/${projectId.value}/ui-automation/browser-profiles`; await mutate<Profile>(profileForm.id ? `${base}/${profileForm.id}` : base, profileForm.id ? 'PUT' : 'POST', payload); profileVisible.value = false; await loadAssets(); Message.success('浏览器配置已保存'); return true } catch (error) { Message.error(error instanceof Error ? error.message : '保存失败'); return false } finally { saving.value = false } }
function resetObject() { Object.assign(objectForm, { id: '', name: '', selectorValue: '', description: '' }) }
function editObject(item: PageObject) { Object.assign(objectForm, item); objectVisible.value = true }
async function saveObject() { saving.value = true; try { const base = `/api/v1/projects/${projectId.value}/ui-automation/page-objects`; await mutate<PageObject>(objectForm.id ? `${base}/${objectForm.id}` : base, objectForm.id ? 'PUT' : 'POST', objectForm); objectVisible.value = false; await loadAssets(); Message.success('页面对象已保存'); return true } catch (error) { Message.error(error instanceof Error ? error.message : '保存失败'); return false } finally { saving.value = false } }
function defaultStep(type: StepType = 'NAVIGATE'): Step { const id = `step-${Date.now().toString(36)}-${scenarioForm.steps.length + 1}`; if (type === 'NAVIGATE') return { id, type, name: '打开页面', url: '/' }; if (type === 'WAIT') return { id, type, name: '等待页面稳定', timeoutMillis: 1000 }; if (type === 'SCREENSHOT') return { id, type, name: '采集页面截图' }; return { id, type, name: stepMeta[type], selector: '', timeoutMillis: 10000 } }
function resetScenario() { Object.assign(scenarioForm, { id: '', name: '', description: '', browserProfileId: profiles.value.find(item => item.enabled)?.id ?? '', failureStrategy: 'STOP', variablesText: '{}', steps: [defaultStep()] }) }
function openScenario() { resetScenario(); scenarioVisible.value = true }
function editScenario(item: Scenario) { Object.assign(scenarioForm, { id: item.id, name: item.name, description: item.description, browserProfileId: item.browserProfileId, failureStrategy: item.failureStrategy, variablesText: JSON.stringify(item.variables, null, 2), steps: item.steps.map((step) => ({ ...step })) }); scenarioVisible.value = true }
function selectorHint(step: Step) { return step.pageObjectId ? `引用页面对象：${pageObjects.value.find((item) => item.id === step.pageObjectId)?.name ?? '已删除'}` : '直接 CSS / Playwright 定位器' }
function requiresSelector(type: StepType) { return ['FILL', 'CLICK', 'ASSERT_VISIBLE', 'ASSERT_TEXT'].includes(type) }
async function saveScenario() { saving.value = true; try { let variables: Record<string, string>; try { variables = JSON.parse(scenarioForm.variablesText || '{}') } catch { throw new Error('场景变量必须是 JSON 对象') }; if (!variables || Array.isArray(variables) || typeof variables !== 'object' || Object.values(variables).some(value => typeof value !== 'string')) throw new Error('场景变量必须是字符串值的 JSON 对象'); const payload = { browserProfileId: scenarioForm.browserProfileId, name: scenarioForm.name, description: scenarioForm.description, failureStrategy: scenarioForm.failureStrategy, variables, steps: scenarioForm.steps }; const base = `/api/v1/projects/${projectId.value}/ui-automation/scenarios`; const saved = await mutate<Scenario>(scenarioForm.id ? `${base}/${scenarioForm.id}` : base, scenarioForm.id ? 'PUT' : 'POST', payload); scenarioVisible.value = false; selectedScenarioId.value = saved.id; await loadAssets(); Message.success('Web UI 场景已保存'); return true } catch (error) { Message.error(error instanceof Error ? error.message : '保存失败'); return false } finally { saving.value = false } }
function openExecution(item: Scenario) { executionScenario.value = item; Object.assign(executeForm, { timeoutSeconds: 300, functionalPlanId: '' }); executeVisible.value = true }
async function execute() { if (!executionScenario.value) return false; saving.value = true; try { const execution = await mutate<Execution>(`/api/v1/projects/${projectId.value}/ui-automation/scenarios/${executionScenario.value.id}/executions`, 'POST', { timeoutSeconds: executeForm.timeoutSeconds, functionalPlanId: executeForm.functionalPlanId || null }); executions.value.unshift(execution); executeVisible.value = false; Message.success('场景已进入 Playwright Runner 队列'); return true } catch (error) { Message.error(error instanceof Error ? error.message : '提交执行失败'); return false } finally { saving.value = false } }
async function cancelExecution(item: Execution) { try { const updated = await mutate<Execution>(`/api/v1/projects/${projectId.value}/ui-automation/executions/${item.id}/cancel`, 'POST'); Object.assign(item, updated); Message.success(updated.status === 'CANCELLED' ? '任务已取消' : '已向 Runner 发出取消指令') } catch (error) { Message.error(error instanceof Error ? error.message : '取消失败') } }
async function retryExecution(item: Execution) { try { const execution = await mutate<Execution>(`/api/v1/projects/${projectId.value}/ui-automation/executions/${item.id}/retry`, 'POST'); executions.value.unshift(execution); Message.success('失败执行已重新排队') } catch (error) { Message.error(error instanceof Error ? error.message : '重试失败') } }
function resetSchedule() { Object.assign(scheduleForm, { id: '', scenarioId: selectedScenarioId.value || scenarios.value[0]?.id || '', functionalPlanId: '', name: '', cronExpression: '0 0 9 ? * MON-FRI', timezone: 'Asia/Shanghai', timeoutSeconds: 300, maxRetryAttempts: 1, retryBackoffSeconds: 30, enabled: true }) }
function editSchedule(item: Schedule) { Object.assign(scheduleForm, { ...item, functionalPlanId: item.functionalPlanId ?? '' }); scheduleVisible.value = true }
async function saveSchedule() { saving.value = true; try { const base = `/api/v1/projects/${projectId.value}/ui-automation/schedules`; await mutate<Schedule>(scheduleForm.id ? `${base}/${scheduleForm.id}` : base, scheduleForm.id ? 'PUT' : 'POST', { ...scheduleForm, functionalPlanId: scheduleForm.functionalPlanId || null }); scheduleVisible.value = false; await loadAssets(); Message.success('定时计划已保存并同步到 Quartz'); return true } catch (error) { Message.error(error instanceof Error ? error.message : '保存定时计划失败'); return false } finally { saving.value = false } }
async function runSchedule(item: Schedule) { try { const execution = await mutate<Execution>(`/api/v1/projects/${projectId.value}/ui-automation/schedules/${item.id}/run`, 'POST'); executions.value.unshift(execution); Message.success('定时计划已进入执行队列') } catch (error) { Message.error(error instanceof Error ? error.message : '立即执行失败') } }
async function loadReport() {
  if (!reportVisible.value || !reportExecutionId.value) return
  const request = ++reportRequest; const project = projectId.value; const id = reportExecutionId.value
  try {
    const data = await read<Report>(`/api/v1/projects/${project}/ui-automation/executions/${id}/report`)
    if (request !== reportRequest || project !== projectId.value || !reportVisible.value) return
    report.value = data; reportError.value = ''
  } catch (error) { if (request === reportRequest) reportError.value = error instanceof Error ? error.message : '加载报告失败' }
}
async function openReport(item: Execution) { closeReport(); reportExecutionId.value = item.id; reportVisible.value = true; await loadReport() }
function closeReport() { reportRequest++; reportVisible.value = false; reportExecutionId.value = ''; report.value = null; reportError.value = '' }

function artifactUrl(item: { id: string }) { return report.value ? `/api/v1/projects/${projectId.value}/ui-automation/executions/${report.value.execution.id}/artifacts/${item.id}/download` : '' }
function artifactViewUrl(item: { id: string }) { return report.value ? `/api/v1/projects/${projectId.value}/ui-automation/executions/${report.value.execution.id}/artifacts/${item.id}/view` : '' }
onMounted(() => {
  void load()
  timer = window.setInterval(() => {
    if (projectId.value) void loadAssets().catch(error => { loadError.value = error instanceof Error ? error.message : '刷新资源失败' })
    if (reportVisible.value) void loadReport()
  }, 3000)
})
onBeforeUnmount(() => { if (timer) window.clearInterval(timer); assetsRequest++; closeReport() })
</script>

<template>
  <div class="page ui-automation-page">
    <PageHeader eyebrow="PLAYWRIGHT RUNNER · ISOLATED EXECUTION" title="Web UI 自动化" description="维护浏览器项目、页面对象和可审计场景；声明式步骤只在受限 Playwright Runner 容器中执行。" action="新建场景" @action="openScenario" />
    <a-alert v-if="loadError" type="warning">{{ loadError }}；正在自动重试。</a-alert>
    <section class="summary panel"><div><span>当前项目</span><strong>{{ selectedProject?.name ?? '未分配' }}</strong><small>{{ selectedProject?.code ?? '—' }}</small></div><a-select v-model="projectId" :style="{ width: '230px' }" @change="changeProject"><a-option v-for="item in projects" :key="item.id" :value="item.id">{{ item.name }}</a-option></a-select><div><span>浏览器配置</span><strong>{{ profiles.length }}</strong><small>{{ profiles.filter((item) => item.enabled).length }} 个已启用</small></div><div><span>页面对象</span><strong>{{ pageObjects.length }}</strong><small>项目级可复用</small></div><div><span>场景</span><strong>{{ scenarios.length }}</strong><small>版本冻结执行清单</small></div><div class="runner"><span>Playwright Runner</span><strong :class="{ ready: executable.length }">{{ executable.length ? `${executable.length} 个已就绪` : '执行禁用' }}</strong><small>{{ activeRunner ? `${activeRunner.runnerId} · ${activeRunner.trustStatus}` : '等待安全心跳' }}</small></div></section>
    <a-alert :type="executable.length ? 'success' : 'info'" :show-icon="true" class="safety-alert">{{ executable.length ? '可信 Runner 已启用。每个场景在独立浏览器上下文中运行，目标 Origin、时限、内存和写入工件均受边界约束。' : 'Runner 尚未启用执行。请先在系统配置中设置 ui-automation.allowed-origins，再为受限 Runner 注入控制面地址和同一目标 Origin 白名单；提交任务不会在当前状态访问任何网页。' }}</a-alert>
    <section class="assets panel"><a-tabs default-active-key="profiles"><a-tab-pane key="profiles" title="浏览器项目"><template #title>浏览器项目 <a-badge :count="profiles.length" :max-count="99" /></template><div class="toolbar"><span>基准 URL 必须命中系统级 Origin 白名单。</span><a-button type="primary" size="small" @click="resetProfile(); profileVisible = true"><icon-plus /> 新建浏览器项目</a-button></div><a-table :data="profiles" :pagination="false" row-key="id" size="small"><template #columns><a-table-column title="名称" data-index="name" /><a-table-column title="浏览器"><template #cell="{ record }"><a-tag color="purple">{{ record.browser }}</a-tag></template></a-table-column><a-table-column title="基准 URL"><template #cell="{ record }"><code>{{ record.baseUrl }}</code></template></a-table-column><a-table-column title="视口"><template #cell="{ record }">{{ record.viewportWidth }} × {{ record.viewportHeight }}</template></a-table-column><a-table-column title="状态"><template #cell="{ record }"><a-tag :color="record.enabled ? 'green' : 'gray'">{{ record.enabled ? '已启用' : '已停用' }}</a-tag></template></a-table-column><a-table-column title="操作"><template #cell="{ record }"><a-button size="mini" @click="editProfile(record)">编辑</a-button></template></a-table-column></template></a-table><a-empty v-if="!loading && profiles.length === 0" description="尚未配置浏览器项目" /></a-tab-pane>
      <a-tab-pane key="objects" title="页面对象"><div class="toolbar"><span>用稳定的定位器抽离页面元素，场景保存时会冻结实际定位器。</span><a-button type="primary" size="small" @click="resetObject(); objectVisible = true"><icon-plus /> 新建页面对象</a-button></div><a-table :data="pageObjects" :pagination="false" row-key="id" size="small"><template #columns><a-table-column title="名称" data-index="name" /><a-table-column title="定位器"><template #cell="{ record }"><code>{{ record.selectorValue }}</code></template></a-table-column><a-table-column title="说明" data-index="description" /><a-table-column title="更新于"><template #cell="{ record }">{{ date(record.updatedAt) }}</template></a-table-column><a-table-column title="操作"><template #cell="{ record }"><a-button size="mini" @click="editObject(record)">编辑</a-button></template></a-table-column></template></a-table><a-empty v-if="!loading && pageObjects.length === 0" description="可先创建登录按钮、搜索框等页面对象" /></a-tab-pane>
      <a-tab-pane key="schedules"><template #title>定时执行 <a-badge :count="schedules.length" :max-count="99" /></template><div class="toolbar"><span>Quartz 使用项目内固定场景；失败按配置退避重试，停止或取消不会自动重试。</span><a-button type="primary" size="small" @click="resetSchedule(); scheduleVisible = true"><icon-plus /> 新建定时计划</a-button></div><a-table :data="schedules" :pagination="false" row-key="id" size="small"><template #columns><a-table-column title="计划" data-index="name" /><a-table-column title="场景"><template #cell="{ record }">{{ scenarios.find((item) => item.id === record.scenarioId)?.name ?? '已删除' }}</template></a-table-column><a-table-column title="功能测试计划"><template #cell="{ record }">{{ record.functionalPlanName || '未关联' }}</template></a-table-column><a-table-column title="Cron"><template #cell="{ record }"><code>{{ record.cronExpression }}</code><small class="code">{{ record.timezone }}</small></template></a-table-column><a-table-column title="重试"><template #cell="{ record }">{{ record.maxRetryAttempts }} 次 · {{ record.retryBackoffSeconds }}s</template></a-table-column><a-table-column title="状态"><template #cell="{ record }"><a-tag :color="record.enabled ? 'green' : 'gray'">{{ record.enabled ? '已启用' : '已停用' }}</a-tag><small v-if="record.lastExecutionStatus" class="code">最近：{{ statusText(record.lastExecutionStatus) }}</small></template></a-table-column><a-table-column title="操作"><template #cell="{ record }"><a-space><a-button size="mini" :disabled="!record.enabled || !executable.length" @click="runSchedule(record)">立即执行</a-button><a-button size="mini" @click="editSchedule(record)">编辑</a-button></a-space></template></a-table-column></template></a-table><a-empty v-if="!loading && schedules.length === 0" description="尚未配置定时执行计划" /></a-tab-pane></a-tabs></section>
    <section class="workspace"><aside class="scenario-list panel"><div class="section-heading"><div><span class="eyebrow">SCENARIOS</span><h3>自动化场景</h3></div><a-button type="text" size="small" @click="resetScenario(); scenarioVisible = true"><icon-plus /></a-button></div><a-spin :loading="loading"><button v-for="item in scenarios" :key="item.id" class="scenario-item" :class="{ selected: selectedScenarioId === item.id }" @click="selectedScenarioId = item.id"><div><strong>{{ item.name }}</strong><small>{{ item.steps.length }} 步 · {{ item.failureStrategy === 'CONTINUE' ? '继续执行' : '失败停止' }}</small></div><a-tag size="small">v{{ item.version }}</a-tag></button><a-empty v-if="!loading && !scenarios.length" description="尚无场景" /></a-spin></aside>
      <main v-if="selectedScenario" class="scenario-detail"><section class="scenario-header panel"><div><span class="eyebrow">SCENARIO · V{{ selectedScenario.version }}</span><h2>{{ selectedScenario.name }}</h2><p>{{ selectedScenario.description || '暂未填写场景说明。' }}</p></div><a-space><a-button :disabled="!executable.length" @click="openExecution(selectedScenario)"><icon-play-circle /> 执行场景</a-button><a-button type="primary" @click="editScenario(selectedScenario)"><icon-edit /> 编辑编排</a-button></a-space></section><section class="scenario-overview panel"><div><span>浏览器项目</span><strong>{{ profiles.find((item) => item.id === selectedScenario?.browserProfileId)?.name ?? '已删除' }}</strong></div><div><span>失败策略</span><strong>{{ selectedScenario.failureStrategy === 'CONTINUE' ? '继续后续步骤' : '首次失败停止' }}</strong></div><div><span>变量</span><strong>{{ Object.keys(selectedScenario.variables).length }}</strong></div><div><span>冻结步骤</span><strong>{{ selectedScenario.steps.length }}</strong></div></section><section class="step-panel panel"><div class="section-heading"><div><span class="eyebrow">DECLARATIVE FLOW</span><h3>步骤编排</h3></div><span class="step-boundary">无脚本 · 无任意网络 · 受控 Runner</span></div><ol class="step-list"><li v-for="(step, index) in selectedScenario.steps" :key="step.id"><span class="step-index">{{ index + 1 }}</span><article><header><a-tag color="arcoblue">{{ stepMeta[step.type] }}</a-tag><strong>{{ step.name }}</strong><small>{{ step.timeoutMillis ? `${step.timeoutMillis}ms` : '默认 30s' }}</small></header><code v-if="step.url">{{ step.url }}</code><code v-if="step.selector">{{ step.selector }}</code><p v-if="step.value">填写：{{ step.value }}</p><p v-if="step.expectedText">期望文本：{{ step.expectedText }}</p><p v-if="step.pageObjectId">页面对象：{{ pageObjects.find((item) => item.id === step.pageObjectId)?.name ?? '已解析到执行清单' }}</p></article></li></ol></section><section class="execution-panel panel"><div class="section-heading"><div><span class="eyebrow">RUN HISTORY</span><h3>执行记录</h3></div><a-button size="small" @click="loadAssets"><icon-refresh /> 刷新</a-button></div><a-table :data="executions.filter((item) => item.scenarioId === selectedScenario?.id)" :pagination="false" row-key="id" size="small"><template #columns><a-table-column title="任务"><template #cell="{ record }"><strong>{{ record.taskId }}</strong><small v-if="record.retryAttempt" class="code">重试 #{{ record.retryAttempt }}</small></template></a-table-column><a-table-column title="状态"><template #cell="{ record }"><a-tag :color="statusColor(record.status)">{{ statusText(record.status) }}</a-tag><small class="code">{{ record.statusCode }}</small></template></a-table-column><a-table-column title="关联"><template #cell="{ record }"><span>{{ record.functionalPlanName || '未关联计划' }}</span><small v-if="record.scheduleId" class="code">定时计划</small></template></a-table-column><a-table-column title="Runner" data-index="runnerId" /><a-table-column title="提交时间"><template #cell="{ record }">{{ date(record.requestedAt) }}</template></a-table-column><a-table-column title="操作"><template #cell="{ record }"><a-space><a-button size="mini" @click="openReport(record)">报告</a-button><a-button v-if="['QUEUED','ACCEPTED','RUNNING','CANCELLING'].includes(record.status)" size="mini" status="warning" :disabled="record.status === 'CANCELLING'" @click="cancelExecution(record)">取消</a-button><a-button v-if="['FAILED','REJECTED','TIMED_OUT'].includes(record.status)" size="mini" @click="retryExecution(record)">重试</a-button></a-space></template></a-table-column></template></a-table><a-empty v-if="!executions.some((item) => item.scenarioId === selectedScenario?.id)" description="当前场景暂无执行记录" /></section></main>
      <main v-else class="panel empty"><a-empty description="选择或创建一个 Web UI 自动化场景"><template #extra><a-button type="primary" @click="resetScenario(); scenarioVisible = true">创建场景</a-button></template></a-empty></main></section>
    <a-modal v-model:visible="profileVisible" :title="profileForm.id ? '编辑浏览器项目' : '新建浏览器项目'" :ok-loading="saving" :on-before-ok="saveProfile"><a-form :model="profileForm" layout="vertical"><a-form-item label="配置名称" required><a-input v-model="profileForm.name" placeholder="例如：订单 Web · Chromium" /></a-form-item><div class="two"><a-form-item label="浏览器"><a-select v-model="profileForm.browser"><a-option value="chromium">Chromium</a-option><a-option value="firefox">Firefox</a-option><a-option value="webkit">WebKit</a-option></a-select></a-form-item><a-form-item label="启用状态"><a-switch v-model="profileForm.enabled" checked-text="启用" unchecked-text="停用" /></a-form-item></div><a-form-item label="基准 URL" required><a-input v-model="profileForm.baseUrl" placeholder="https://web.example.test" /><template #extra>只能使用系统配置 ui-automation.allowed-origins 中列出的 Origin。</template></a-form-item><div class="two"><a-form-item label="视口宽度"><a-input-number v-model="profileForm.viewportWidth" :min="320" :max="3840" /></a-form-item><a-form-item label="视口高度"><a-input-number v-model="profileForm.viewportHeight" :min="320" :max="2160" /></a-form-item></div></a-form></a-modal>
    <a-modal v-model:visible="objectVisible" :title="objectForm.id ? '编辑页面对象' : '新建页面对象'" :ok-loading="saving" :on-before-ok="saveObject"><a-form :model="objectForm" layout="vertical"><a-form-item label="名称" required><a-input v-model="objectForm.name" placeholder="例如：登录按钮" /></a-form-item><a-form-item label="定位器" required><a-input v-model="objectForm.selectorValue" placeholder="例如：[data-testid='login-submit']" /></a-form-item><a-form-item label="说明"><a-textarea v-model="objectForm.description" :auto-size="{ minRows: 2, maxRows: 4 }" /></a-form-item></a-form></a-modal>
    <a-modal v-model:visible="executeVisible" title="执行 Web UI 场景" :ok-loading="saving" :on-before-ok="execute"><a-form :model="executeForm" layout="vertical"><a-alert type="info" :show-icon="true" class="execute-hint">执行清单会在入队时冻结，浏览器与网络访问仅发生在隔离的 Playwright Runner 内。</a-alert><a-form-item label="执行超时（秒）"><a-input-number v-model="executeForm.timeoutSeconds" :min="10" :max="3600" /></a-form-item><a-form-item label="关联功能测试计划（可选）"><a-select v-model="executeForm.functionalPlanId" allow-clear placeholder="把这次自动化执行纳入功能测试追溯"><a-option v-for="item in functionalPlans" :key="item.id" :value="item.id">{{ item.planCode }} · {{ item.name }}</a-option></a-select><template #extra>关联后会在执行记录和报告中保留计划快照；不会改写功能测试用例的人工执行结果。</template></a-form-item></a-form></a-modal>
    <a-modal v-model:visible="scheduleVisible" :title="scheduleForm.id ? '编辑定时计划' : '新建定时计划'" width="680px" :ok-loading="saving" :on-before-ok="saveSchedule"><a-form :model="scheduleForm" layout="vertical"><div class="two"><a-form-item label="计划名称" required><a-input v-model="scheduleForm.name" placeholder="例如：工作日登录巡检" /></a-form-item><a-form-item label="执行场景" required><a-select v-model="scheduleForm.scenarioId"><a-option v-for="item in scenarios" :key="item.id" :value="item.id">{{ item.name }}</a-option></a-select></a-form-item></div><a-form-item label="关联功能测试计划（可选）"><a-select v-model="scheduleForm.functionalPlanId" allow-clear placeholder="不关联"><a-option v-for="item in functionalPlans" :key="item.id" :value="item.id">{{ item.planCode }} · {{ item.name }}</a-option></a-select></a-form-item><div class="two"><a-form-item label="Quartz Cron" required><a-input v-model="scheduleForm.cronExpression" placeholder="0 0 9 ? * MON-FRI" /></a-form-item><a-form-item label="时区" required><a-select v-model="scheduleForm.timezone"><a-option value="Asia/Shanghai">Asia/Shanghai</a-option><a-option value="UTC">UTC</a-option></a-select></a-form-item></div><div class="three"><a-form-item label="执行超时（秒）"><a-input-number v-model="scheduleForm.timeoutSeconds" :min="10" :max="3600" /></a-form-item><a-form-item label="失败重试次数"><a-input-number v-model="scheduleForm.maxRetryAttempts" :min="0" :max="5" /></a-form-item><a-form-item label="重试间隔（秒）"><a-input-number v-model="scheduleForm.retryBackoffSeconds" :min="5" :max="3600" /></a-form-item></div><a-form-item label="启用计划"><a-switch v-model="scheduleForm.enabled" checked-text="启用" unchecked-text="停用" /></a-form-item><a-alert type="warning" :show-icon="true">重试仅在 Runner 返回失败、拒绝或超时时执行；用户主动取消不会重新排队。Cron 使用 Quartz 的六或七段格式。</a-alert></a-form></a-modal>
    <a-modal v-model:visible="scenarioVisible" :title="scenarioForm.id ? '编辑 Web UI 场景' : '新建 Web UI 场景'" width="920px" :ok-loading="saving" :on-before-ok="saveScenario"><a-form :model="scenarioForm" layout="vertical"><div class="two"><a-form-item label="场景名称" required><a-input v-model="scenarioForm.name" placeholder="例如：用户登录成功" /></a-form-item><a-form-item label="浏览器项目" required><a-select v-model="scenarioForm.browserProfileId" placeholder="选择已启用配置"><a-option v-for="item in profiles.filter((item) => item.enabled)" :key="item.id" :value="item.id">{{ item.name }} · {{ item.browser }}</a-option></a-select></a-form-item></div><a-form-item label="场景说明"><a-textarea v-model="scenarioForm.description" :auto-size="{ minRows: 2, maxRows: 3 }" /></a-form-item><div class="two"><a-form-item label="失败策略"><a-radio-group v-model="scenarioForm.failureStrategy"><a-radio value="STOP">首次失败停止</a-radio><a-radio value="CONTINUE">失败后继续</a-radio></a-radio-group></a-form-item><a-form-item label="变量（JSON 对象）"><a-textarea v-model="scenarioForm.variablesText" :auto-size="{ minRows: 2, maxRows: 4 }" placeholder="{ &quot;account&quot;: &quot;demo&quot; }" /></a-form-item></div><div class="form-heading"><div><strong>声明式步骤</strong><span>变量使用 <code v-pre>{{variable}}</code>；不会在控制面执行用户脚本。</span></div><a-select :model-value="'NAVIGATE'" :style="{ width: '150px' }" @change="(value) => scenarioForm.steps.push(defaultStep(value as StepType))"><a-option v-for="type in Object.keys(stepMeta)" :key="type" :value="type">添加 {{ stepMeta[type as StepType] }}</a-option></a-select></div><article v-for="(step, index) in scenarioForm.steps" :key="step.id" class="step-form"><header><strong>步骤 {{ index + 1 }}</strong><a-space><a-select v-model="step.type" :style="{ width: '130px' }"><a-option v-for="type in Object.keys(stepMeta)" :key="type" :value="type">{{ stepMeta[type as StepType] }}</a-option></a-select><a-button type="text" status="danger" :disabled="scenarioForm.steps.length === 1" @click="scenarioForm.steps.splice(index, 1)"><icon-delete /></a-button></a-space></header><div class="step-grid"><a-form-item label="步骤名称"><a-input v-model="step.name" /></a-form-item><a-form-item v-if="step.type === 'NAVIGATE'" label="页面路径"><a-input v-model="step.url" placeholder="/login 或 https://same-origin/path" /></a-form-item><a-form-item v-else-if="step.type === 'WAIT'" label="等待毫秒"><a-input-number v-model="step.timeoutMillis" :min="1" :max="60000" /></a-form-item><a-form-item v-else-if="requiresSelector(step.type)" label="页面对象（可选）"><a-select v-model="step.pageObjectId" allow-clear placeholder="引用已维护对象"><a-option v-for="item in pageObjects" :key="item.id" :value="item.id">{{ item.name }}</a-option></a-select></a-form-item></div><a-form-item v-if="requiresSelector(step.type)" label="定位器"><a-input v-model="step.selector" :disabled="!!step.pageObjectId" :placeholder="selectorHint(step)" /></a-form-item><a-form-item v-if="step.type === 'FILL'" label="填写内容"><a-input v-model="step.value" placeholder="可使用 {{account}}" /></a-form-item><a-form-item v-if="step.type === 'ASSERT_TEXT'" label="期望文本"><a-input v-model="step.expectedText" /></a-form-item><a-form-item v-if="step.type !== 'WAIT' && step.type !== 'SCREENSHOT'" label="步骤超时（毫秒）"><a-input-number v-model="step.timeoutMillis" :min="100" :max="60000" /></a-form-item></article></a-form></a-modal>
    <a-drawer v-model:visible="reportVisible" width="760px" :footer="false" @cancel="closeReport"><template #title>Web UI 自动化报告</template><a-alert v-if="reportError" type="error">{{ reportError }}</a-alert><a-spin :loading="!report && !reportError"><template v-if="report"><section class="report-title"><div><strong>{{ report.execution.scenarioName }}</strong><small>{{ report.execution.taskId }}</small></div><a-tag :color="statusColor(report.execution.status)">{{ statusText(report.execution.status) }}</a-tag></section><div class="report-summary"><div><span>步骤数</span><strong>{{ report.summary.totalSteps }}</strong></div><div><span>通过</span><strong>{{ report.summary.passedSteps }}</strong></div><div><span>失败</span><strong>{{ report.summary.failedSteps }}</strong></div><div><span>累计耗时</span><strong>{{ report.summary.totalDurationMillis }}ms</strong></div></div><section v-if="firstFailedStep" class="failure-locator"><div><span class="eyebrow">FAILURE LOCATOR</span><h3>#{{ firstFailedStep.stepSequence }} · {{ firstFailedStep.stepName }}</h3><p>{{ firstFailedStep.errorMessage || 'Runner 未提供额外错误信息。' }}</p></div><a-tag color="red">{{ firstFailedStep.stepType }}</a-tag></section><section class="report-section"><h3>步骤结果</h3><a-timeline><a-timeline-item v-for="step in report.steps" :key="step.id" :dot-color="step.outcome === 'PASSED' ? 'green' : 'red'" :label="`#${step.stepSequence} · ${step.durationMillis}ms`"><strong>{{ step.stepName }}</strong><a-tag size="small" :color="step.outcome === 'PASSED' ? 'green' : 'red'">{{ step.outcome }}</a-tag><p v-if="step.errorMessage">{{ step.errorMessage }}</p></a-timeline-item></a-timeline><a-empty v-if="!report.steps.length" description="等待 Runner 回传步骤结果" /></section><section class="report-section"><h3>工件与失败现场</h3><div v-if="visualArtifacts.length" class="visual-artifacts"><article v-for="item in visualArtifacts" :key="item.id" class="visual-artifact"><a-image v-if="item.artifactType === 'SCREENSHOT'" :src="artifactViewUrl(item)" :alt="item.originalName" width="100%" /><video v-else controls preload="metadata" :src="artifactViewUrl(item)">当前浏览器不支持视频预览。</video><div><strong>{{ item.artifactType === 'SCREENSHOT' ? '截图' : '执行视频' }}</strong><small>{{ item.originalName }} · {{ size(item.sizeBytes) }} · {{ date(item.createdAt) }}</small></div></article></div><div v-for="item in report.artifacts.filter((entry) => entry.artifactType === 'TRACE')" :key="item.id" class="artifact"><div><strong>TRACE</strong><small>{{ item.originalName }} · {{ size(item.sizeBytes) }} · 可在 Playwright Trace Viewer 中打开</small></div><a-link :href="artifactUrl(item)" target="_blank">下载 Trace</a-link></div><a-empty v-if="!report.artifacts.length" description="Runner 完成后将归档截图、Trace 和视频" /></section></template></a-spin></a-drawer>
  </div>
</template>

